public:
    OrangeCat(string n, int f) : Cat(n), fish(f) {}
    void speak() const override {
        cout << name << "：本喵是橘猫，吃了 " << fish << " 条，喵喵喵！" << endl;
    }
};

int main() {
    int f = 0;
    cin >> f;

    OrangeCat o("大胖", f);
    Cat& r = o;
    cout << "牌子写「猫」，喊出来：";
    r.speak();
    cout << "写「橘猫」的名字，喊出来：";
    o.speak();
    return 0;
}
